// PendingMapper registers a (platform, event) pair whose real mapper
// hasn't landed. Map returns WEBHOOK_MAPPER_PENDING so the handler
// surfaces a graceful "not implemented" rather than a 500.
type PendingMapper struct {
	platform enums.WebhookPlatform
	event    wire.SyncEventName
}

func NewPendingMapper(platform enums.WebhookPlatform, event wire.SyncEventName) *PendingMapper {
	return &PendingMapper{platform: platform, event: event}
}
func (m *PendingMapper) Platform() enums.WebhookPlatform { return m.platform }
func (m *PendingMapper) Event() wire.SyncEventName       { return m.event }
func (m *PendingMapper) Map(_ context.Context, _ []byte, _ MapContext) ([]types.DomainEventI, error) {
	return nil, coreerrors.NewBaseError(ctxerrors.CodeWebhookMapperPending,
		"webhook mapper pending for "+string(m.platform)+"/"+string(m.event))
}

