func TestStripeVerifier_AcceptsValidSignature(t *testing.T) {
	secret := "whsec_test"
	body := []byte(`{"id":"evt_1"}`)
	timestamp := "1716355200"

	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(timestamp))
	mac.Write([]byte("."))
	mac.Write(body)
	sig := hex.EncodeToString(mac.Sum(nil))
	header := fmt.Sprintf("t=%s,v1=%s", timestamp, sig)

	ok, err := services.NewStripeVerifier(secret).Verify(body, header)
	if err != nil || !ok {
		t.Fatalf("expected accept, got ok=%v err=%v", ok, err)
	}
}

func TestStripeVerifier_AcceptsAnyOfMultipleV1Sigs(t *testing.T) {
	secret := "whsec_test"
	body := []byte(`{"id":"evt_1"}`)
	timestamp := "1716355200"

	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(timestamp))
	mac.Write([]byte("."))
	mac.Write(body)
	sig := hex.EncodeToString(mac.Sum(nil))

	// First v1= is bogus, second is correct — should still accept.
	header := fmt.Sprintf("t=%s,v1=deadbeef,v1=%s", timestamp, sig)
	ok, _ := services.NewStripeVerifier(secret).Verify(body, header)
	if !ok {
		t.Fatal("expected accept on second v1= match")
	}
}

