package services

import (
	"crypto/hmac"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"hash"

	"template/api-go/internal/sync/enums"
)

// HMACAlg + Encoding select the per-platform variant of "HMAC over raw
// body, compare to header". A new platform that follows this shape
// (NuvemShop/Yampi/Kiwify/CartPanda today) only needs a one-line
// constructor + an env lookup — no fresh verifier code.

type HMACAlg int

const (
	HMACSHA1 HMACAlg = iota
	HMACSHA256
	HMACSHA512
)

type HMACEncoding int

const (
	HexLower HMACEncoding = iota
	Base64Std
)

// HMACVerifier is the shared body of every plain-HMAC provider. Pin
// the platform enum, the signature header, the alg, the encoding,
// and one or more secrets at construction. A signature is accepted
// when ANY configured secret matches — supports rotation and multiple
// signing keys (e.g. one per product/store) in a single env var.
// Returns false when no secrets are configured (fail-closed).
type HMACVerifier struct {
	platform enums.WebhookPlatform
	header   string
	alg      HMACAlg
	encoding HMACEncoding
	secrets  [][]byte
}

func NewHMACVerifier(platform enums.WebhookPlatform, header string, alg HMACAlg, encoding HMACEncoding, secrets ...string) *HMACVerifier {
	v := &HMACVerifier{platform: platform, header: header, alg: alg, encoding: encoding}
	for _, s := range secrets {
		if s == "" {
			continue
		}
		v.secrets = append(v.secrets, []byte(s))
	}
	return v
}

func (v *HMACVerifier) Platform() enums.WebhookPlatform { return v.platform }
func (v *HMACVerifier) SignatureHeader() string         { return v.header }

func (v *HMACVerifier) Verify(rawBody []byte, signature string) (bool, error) {
	if signature == "" || len(v.secrets) == 0 {
		return false, nil
	}
	expected, ok := v.decode(signature)
	if !ok {
		return false, nil
	}
	for _, secret := range v.secrets {
		mac := hmac.New(v.hashCtor(), secret)
		mac.Write(rawBody)
		if subtle.ConstantTimeCompare(expected, mac.Sum(nil)) == 1 {
			return true, nil
		}
	}
	return false, nil
}

func (v *HMACVerifier) hashCtor() func() hash.Hash {
	switch v.alg {
	case HMACSHA1:
		return sha1.New
	case HMACSHA256:
		return sha256.New
	case HMACSHA512:
		return sha512.New
	}
	return sha256.New
}

func (v *HMACVerifier) decode(signature string) ([]byte, bool) {
	switch v.encoding {
	case HexLower:
		b, err := hex.DecodeString(signature)
		if err != nil {
			return nil, false
		}
		return b, true
	case Base64Std:
		b, err := base64.StdEncoding.DecodeString(signature)
		if err != nil {
			return nil, false
		}
		return b, true
	}
	return nil, false
}

