// pendingPipelineProviders builds fx providers for each
// (platform, name) pair that has no real implementation yet.
// Each provider returns a PendingPipeline that surfaces ErrPipelinePending.
//
// Two matrices are registered:
//
//  1. Non-Shopify platforms × {ORDERS, PRODUCTS} — the original stubs
//     (Spec A). CART_PANDA/YAMPI/KIWIFY are string literals; the
//     wire.SalesPlatform constants for those platforms were removed from
//     the contracts in the polyglot restructure. NUVEM_SHOP remains a
//     valid SalesPlatform.
//
//  2. All platforms × new kinds (DISPUTES, MARKETING_METRICS,
//     MARKETING_METRICS_CONCURRENT, MARKETING_METRICS_TWO_PHASE,
//     CAMPAIGNS) — TRANSACTIONS is intentionally excluded because
//     NewShopifyTransactionsPipeline is the real impl for
//     (SHOPIFY, TRANSACTIONS); adding it here would collide in the
//     factory (last-write-wins) and risk shadowing the real pipeline.
//
// Matrix 3 (marketing platforms) is fully implemented:
//   - META × {BUSINESS_ACCOUNTS, AD_ACCOUNTS, CAMPAIGNS, MARKETING_METRICS}
//   - TIKTOK × {BUSINESS_ACCOUNTS, AD_ACCOUNTS, CAMPAIGNS, MARKETING_METRICS}
//   - GOOGLE_ADS × {BUSINESS_ACCOUNTS, AD_ACCOUNTS, CAMPAIGNS, MARKETING_METRICS}
func pendingPipelineProviders() []fx.Option {
	// --- Matrix 1: non-Shopify/non-Nuvemshop platforms × existing kinds ---
	// NUVEM_SHOP is removed here; it has real implementations registered above.
	nonShopifyPlatforms := []wire.SalesPlatform{
		"CART_PANDA",
		"YAMPI",
		"KIWIFY",
	}
	existingNames := []enums.SyncPipelineName{
		enums.SyncPipelineOrders,
		enums.SyncPipelineProducts,
	}

	// --- Matrix 2: all platforms × new kinds (TRANSACTIONS excluded) ---
	// NUVEM_SHOP is included here for new kinds (DISPUTES, etc.) since only
	// ORDERS and PRODUCTS have real implementations; the rest remain pending.
	allPlatforms := append([]wire.SalesPlatform{wire.SalesPlatformSHOPIFY, wire.SalesPlatformNUVEM_SHOP}, nonShopifyPlatforms...)
	newNames := []enums.SyncPipelineName{
		enums.SyncPipelineDisputes,
		enums.SyncPipelineMarketingMetrics,
		enums.SyncPipelineMarketingMetricsConcurrent,
		enums.SyncPipelineMarketingMetricsTwoPhase,
		enums.SyncPipelineCampaigns,
	}

	capacity := len(nonShopifyPlatforms)*len(existingNames) + len(allPlatforms)*len(newNames)
	out := make([]fx.Option, 0, capacity)

	for _, p := range nonShopifyPlatforms {
		for _, n := range existingNames {
			plat := p
			name := n
			out = append(out, fx.Provide(fx.Annotate(
				func() pipelines.Pipeline { return pipelines.NewPendingPipeline(plat, name) },
				fx.ResultTags(`group:"pipelines"`),
			)))
		}
	}

	for _, p := range allPlatforms {
		for _, n := range newNames {
			plat := p
			name := n
			out = append(out, fx.Provide(fx.Annotate(
				func() pipelines.Pipeline { return pipelines.NewPendingPipeline(plat, name) },
				fx.ResultTags(`group:"pipelines"`),
			)))
		}
	}

	return out
}

