package services_test

import (
	"crypto/hmac"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base64"
	"encoding/hex"
	"hash"
	"testing"

	"template/api-go/internal/sync/enums"
	"template/api-go/internal/webhooks/services"
)

func sign(alg func() hash.Hash, secret, body []byte, encoding services.HMACEncoding) string {
	mac := hmac.New(alg, secret)
	mac.Write(body)
	sum := mac.Sum(nil)
	switch encoding {
	case services.HexLower:
		return hex.EncodeToString(sum)
	case services.Base64Std:
		return base64.StdEncoding.EncodeToString(sum)
	}
	return ""
}

func TestHMACVerifier_AcceptsValidSignatures(t *testing.T) {
	cases := []struct {
		name     string
		alg      services.HMACAlg
		hashCtor func() hash.Hash
		platform enums.WebhookPlatform
	}{
		{"sha1 hex", services.HMACSHA1, sha1.New, enums.WebhookPlatformKiwify},
		{"sha256 hex", services.HMACSHA256, sha256.New, enums.WebhookPlatformNuvemShop},
		{"sha512 hex", services.HMACSHA512, sha512.New, enums.WebhookPlatformCartPanda},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			v := services.NewHMACVerifier(tc.platform, "X-Test-Signature", tc.alg, services.HexLower, "topsecret")
			body := []byte(`{"id":1}`)
			sig := sign(tc.hashCtor, []byte("topsecret"), body, services.HexLower)
			ok, err := v.Verify(body, sig)
			if err != nil || !ok {
				t.Fatalf("expected accept, got ok=%v err=%v", ok, err)
			}
		})
	}
}

func TestHMACVerifier_RejectsBadSignature(t *testing.T) {
	v := services.NewHMACVerifier(enums.WebhookPlatformNuvemShop, "X-Linkedstore-Hmac-Sha256", services.HMACSHA256, services.HexLower, "topsecret")
	ok, _ := v.Verify([]byte(`{"id":1}`), "deadbeef")
	if ok {
		t.Fatal("expected reject")
	}
}

func TestHMACVerifier_FailsClosedOnMissingSecret(t *testing.T) {
	v := services.NewHMACVerifier(enums.WebhookPlatformYampi, "X-Yampi-Hmac-Sha256", services.HMACSHA256, services.HexLower, "")
	ok, _ := v.Verify([]byte(`{}`), "any")
	if ok {
		t.Fatal("expected reject when secret empty")
	}
}

func TestHMACVerifier_RejectsInvalidEncoding(t *testing.T) {
	v := services.NewHMACVerifier(enums.WebhookPlatformYampi, "X-Yampi-Hmac-Sha256", services.HMACSHA256, services.HexLower, "topsecret")
	ok, _ := v.Verify([]byte(`{}`), "not-hex-zzz")
	if ok {
		t.Fatal("expected reject on undecodable signature")
	}
}

func TestHMACVerifier_AcceptsAnyOfMultipleSecrets(t *testing.T) {
	v := services.NewHMACVerifier(enums.WebhookPlatformKiwify, "X-Kiwify-Signature", services.HMACSHA1, services.HexLower, "first", "second", "third")
	body := []byte(`{"id":1}`)

	for _, secret := range []string{"first", "second", "third"} {
		sig := sign(sha1.New, []byte(secret), body, services.HexLower)
		ok, err := v.Verify(body, sig)
		if err != nil || !ok {
			t.Fatalf("expected accept for secret %q, got ok=%v err=%v", secret, ok, err)
		}
	}

	unknown := sign(sha1.New, []byte("not-configured"), body, services.HexLower)
	ok, _ := v.Verify(body, unknown)
	if ok {
		t.Fatal("expected reject for signature produced by an unconfigured secret")
	}
}

func TestHMACVerifier_SkipsEmptySecretsInVariadic(t *testing.T) {
	v := services.NewHMACVerifier(enums.WebhookPlatformKiwify, "X-Kiwify-Signature", services.HMACSHA1, services.HexLower, "", "real", "")
	body := []byte(`{"id":1}`)
	sig := sign(sha1.New, []byte("real"), body, services.HexLower)
	ok, err := v.Verify(body, sig)
	if err != nil || !ok {
		t.Fatalf("expected accept after empty entries filtered, got ok=%v err=%v", ok, err)
	}
}

func TestHMACVerifier_FailsClosedOnAllEmptyVariadic(t *testing.T) {
	v := services.NewHMACVerifier(enums.WebhookPlatformKiwify, "X-Kiwify-Signature", services.HMACSHA1, services.HexLower, "", "")
	ok, _ := v.Verify([]byte(`{}`), "any")
	if ok {
		t.Fatal("expected reject when every variadic secret is empty")
	}
}

