	ok, _ := services.NewStripeVerifier("").Verify([]byte(`{}`), "t=123,v1=abc")
	if ok {
		t.Fatal("expected reject on empty secret")
	}
}

func TestMetaVerifier_StripsPrefixAndAccepts(t *testing.T) {
	secret := "app_secret"
	body := []byte(`{"object":"page"}`)
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(body)
	sig := "sha256=" + hex.EncodeToString(mac.Sum(nil))

	ok, _ := services.NewMetaVerifier(secret).Verify(body, sig)
	if !ok {
		t.Fatal("expected accept after stripping sha256= prefix")
	}
}

func TestMetaVerifier_RejectsWithoutPrefix(t *testing.T) {
	v := services.NewMetaVerifier("app_secret")
	if ok, _ := v.Verify([]byte(`{}`), "deadbeef"); ok {
		t.Fatal("expected reject for bad sig regardless of prefix")
	}
}

func TestTikTokVerifier_AcceptsValidSignature(t *testing.T) {
	secret := "tiktok"
	body := []byte(`{}`)
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(body)
	sig := hex.EncodeToString(mac.Sum(nil))

	ok, _ := services.NewTikTokVerifier(secret).Verify(body, sig)
	if !ok {
		t.Fatal("expected accept")
	}
}

func TestGoogleAdsVerifier_AcceptsMatchingToken(t *testing.T) {
	ok, _ := services.NewGoogleAdsVerifier("expected-token").Verify(nil, "expected-token")
	if !ok {
		t.Fatal("expected accept for matching token")
	}
}

func TestGoogleAdsVerifier_RejectsMismatch(t *testing.T) {
	v := services.NewGoogleAdsVerifier("expected-token")
	if ok, _ := v.Verify(nil, "wrong-token"); ok {
		t.Fatal("expected reject")
	}
}

func TestGoogleAdsVerifier_FailsClosedOnEmpty(t *testing.T) {
	v := services.NewGoogleAdsVerifier("")
	if ok, _ := v.Verify(nil, "anything"); ok {
		t.Fatal("expected reject when expected token unset")
	}
}

